// Generated by local model ornith:9b (3 review rounds), verified by Claude's tests.
import { useEffect, useRef, useState } from "react";

export function formatCurrency(n: number): string {
  const rounded = Math.round(Number(n) || 0);
  if (rounded < 0) return `−₹${Math.abs(rounded).toLocaleString("en-IN")}`;
  return `₹${rounded.toLocaleString("en-IN")}`;
}

export function formatReturn(n: number): string {
  const v = Number(n) || 0;
  if (v > 0) return `+${v.toFixed(2)}%`;
  if (v < 0) return `−${Math.abs(v).toFixed(2)}%`;
  return "0.00%";
}

export function formatExitReason(reason: string | null | undefined): string {
  if (!reason || /^\s*$/.test(reason)) return "Exit";
  return reason.toLowerCase().replace(/_/g, " ").replace(/\s+/g, " ").trim().replace(/^(.{1})/, (m) => m.toUpperCase());
}

export function sortMonthsDesc<T extends { month: string }>(rows: T[] | null | undefined): T[] {
  if (!rows) return [];
  return [...rows].sort((a, b) => b.month.localeCompare(a.month));
}

export type OriginFilter = "LIVE" | "SIMULATED" | "ALL";

export function useOriginFilter(liveCount: number | undefined) {
  const [filter, setFilter] = useState<OriginFilter>("ALL");
  const hasBeenLive = useRef(false);
  useEffect(() => {
    if ((liveCount ?? 0) > 0 && !hasBeenLive.current) {
      hasBeenLive.current = true;
      setFilter("LIVE");
    }
  }, [liveCount]);
  return [filter, setFilter] as const;
}
